after:
public class ReportLine {
    static String padRight(String s, int width) {
        String n = s;
        while (n.length() < width) {
            n = n + " ";
        }
        return n;
    }

    public static String format(String name, int qty) {
        return padRight(name, 12) + "| " + qty;
    }
}

